  // playhead in seconds, the unit the source places clips in; null when no scene is active or no project is open
  currentTime: number | null;
  // families registered in the world drawing the project; the editor default is always among them
  fontFamilies: Array<string>;
  generations: Array<{
    // the library path the generation landed as, on done rows — ready for media_probe and its siblings
