```ts
declare const tools: { mcp__grafana__update_dashboard(args: {
  // The full dashboard JSON: classic v1 (panels[]) or v2 (elements/layout; skeleton in the tool description). Use for creating new dashboards or complete updates. Saved dashboard annotation queries/definitions live in 'annotations.list' inside this JSON; they are different from annotation events, which are stored separately. Large dashboards consume significant context - consider using patches for small changes.
  dashboard?: { [key: string]: unknown; };
  // The UID of the dashboard's folder
  folderUid?: string;
  // Set a commit message for the version history
  message?: string;
  // Array of patch operations for targeted updates. More efficient than full dashboard JSON for small changes. Common paths: '$.templating.list/-' to add a variable, '$.annotations.list/-' to add a saved dashboard annotation query/definition, '$.panels[0].targets[0].expr' to replace a panel query. v2 paths: '$.elements.<name>.spec.title', '$.variables/-', '$.layout.spec.items/-'.
  operations?: Array<{
    // Operation type: 'replace', 'add', 'remove'
    op: string;
    // JSONPath to the property to modify. Supports: '$.title', '$.panels[0].title', '$.panels[0].targets[0].expr', '$.panels[1].targets[0].datasource', '$.templating.list/-' (append a variable), '$.annotations.list/-' (append a saved dashboard annotation query/definition). For appending to arrays, use '/- ' syntax: '$.panels/- ' (append to panels array) or '$.panels[2]/- ' (append to nested array at index 2).
    path: string;
    // New value for replace/add operations. When adding a saved dashboard annotation query/definition, append an object to '$.annotations.list'.
    value?: string | number | boolean | { [key: string]: unknown; } | unknown[] | null;
  }>;
  // Overwrite the dashboard if it exists. Otherwise create one
  overwrite?: boolean;
  // UID of existing dashboard to update. Must be used together with 'operations'. Providing 'uid' without 'operations' will fail.
  uid?: string;
  // ID of the user making the change
